import { useState } from "react";
import { Mail, Phone, MapPin, Send } from "lucide-react";

export default function Contact() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: "",
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Message envoyé avec succès !");
    setFormData({ name: "", email: "", message: "" });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-blue-100 py-20 px-6">
      <div className="max-w-6xl mx-auto">
        {/* TITLE */}
        <div className="text-center mb-16">
          <h1 className="text-5xl md:text-6xl font-extrabold bg-gradient-to-r from-indigo-600 to-blue-600 bg-clip-text text-transparent">
            Contactez-nous
          </h1>
          <p className="text-gray-600 mt-4 text-lg max-w-2xl mx-auto">
            Une question ? Un projet ? Nous sommes disponibles pour vous
            accompagner rapidement et efficacement.
          </p>
        </div>

        {/* GRID */}
        <div className="grid md:grid-cols-2 gap-12">
          {/* INFO CARDS */}
          <div className="space-y-8">
            {[
              {
                icon: Mail,
                title: "Email",
                content: "contact@entreprise.com",
                color: "from-blue-500 to-indigo-600",
              },
              {
                icon: Phone,
                title: "Téléphone",
                content: "+33 6 12 34 56 78",
                color: "from-green-500 to-emerald-600",
              },
              {
                icon: MapPin,
                title: "Adresse",
                content: "123 Rue de Paris, France",
                color: "from-purple-500 to-pink-600",
              },
            ].map((item, idx) => (
              <div
                key={idx}
                className="group p-8 bg-white/60 backdrop-blur-xl rounded-3xl shadow-xl border border-white hover:shadow-2xl transition duration-500"
              >
                <div
                  className={`w-14 h-14 flex items-center justify-center rounded-2xl bg-gradient-to-br ${item.color} text-white shadow-lg group-hover:scale-110 transition transform duration-300`}
                >
                  <item.icon className="w-7 h-7" />
                </div>
                <h3 className="mt-5 text-2xl font-bold text-gray-800">
                  {item.title}
                </h3>
                <p className="text-gray-600 mt-1 text-lg">{item.content}</p>
              </div>
            ))}
          </div>

          {/* FORM */}
          <div className="bg-white rounded-3xl shadow-2xl p-10 border border-gray-100">
            <form onSubmit={handleSubmit} className="space-y-8">
              {/* NAME */}
              <div>
                <label className="text-gray-700 font-medium">Nom complet</label>
                <input
                  type="text"
                  placeholder="Votre nom"
                  className="mt-2 w-full px-5 py-4 bg-gray-50 border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-blue-500 focus:outline-none text-lg"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  required
                />
              </div>

              {/* EMAIL */}
              <div>
                <label className="text-gray-700 font-medium">Email</label>
                <input
                  type="email"
                  placeholder="email@example.com"
                  className="mt-2 w-full px-5 py-4 bg-gray-50 border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-blue-500 focus:outline-none text-lg"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  required
                />
              </div>

              {/* MESSAGE */}
              <div>
                <label className="text-gray-700 font-medium">Message</label>
                <textarea
                  rows="5"
                  placeholder="Écrivez votre message..."
                  className="mt-2 w-full px-5 py-4 bg-gray-50 border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-blue-500 focus:outline-none text-lg"
                  value={formData.message}
                  onChange={(e) =>
                    setFormData({ ...formData, message: e.target.value })
                  }
                  required
                ></textarea>
              </div>

              {/* BUTTON */}
              <button
                type="submit"
                className="w-full bg-gradient-to-r from-indigo-600 to-blue-600 text-white text-xl font-semibold py-4 rounded-xl shadow-lg hover:shadow-2xl transition transform hover:-translate-y-1 flex items-center justify-center gap-2"
              >
                Envoyer
                <Send className="w-5 h-5" />
              </button>
            </form>
          </div>
        </div>

        {/* CTA */}
        <div className="mt-20 text-center">
          <p className="text-gray-500 text-lg">
            📩 Nous répondons en moins de <span className=" font-semibold">1 heure</span>
          </p>
        </div>
      </div>
    </div>
  );
}
